example.code:
// Return successfully:
AvatarOptionObject.ToReturn(tngnWsvcSession, 0);

// Return with an error:
AvatarOptionObject.ToReturn(tngnWsvcSession, 1, "You shall not pass!");

AvatarOptionObject.ExportOptObj(sentOptionObject, @"C:\Tingen_Data\exports");
// Produces:
//   C:\Tingen_Data\exports\exported-optionobject-20260515_103045.html
//   C:\Tingen_Data\exports\exported-optionobject-20260515_103045.json

var message = AvatarScriptParameter.VerifyExistence("_OpenIncident");
Console.WriteLine(message);
// Output: "The sent script parameter ('_OpenIncident') does exist."

var missing = AvatarScriptParameter.VerifyExistence("");
Console.WriteLine(missing);
// Output: "The sent script parameter ('') does not exist."

// Routes to SpecificFormRequest when prefixed with "_":
tngnWsvcSession.ScriptParameter.OriginalScriptParameter = "_OpenIncident";
AvatarScriptParameter.Parse(tngnWsvcSession);

// Routes to StandAloneRequest otherwise:
tngnWsvcSession.ScriptParameter.OriginalScriptParameter = "catchoptionobject";
AvatarScriptParameter.Parse(tngnWsvcSession);

// Dispatches to OptObjUtility.CatchOptionObject:
tngnWsvcSession.ScriptParameter.OriginalScriptParameter = "catchoptionobject";
AvatarScriptParameter.StandAloneRequest(tngnWsvcSession);

var callerInfo = LogComponents.GetCallerInfo();
var logLines   = log_DoseChangeEval.PrescriberIsAuthorizing(callerInfo, "SELECT * FROM staff WHERE Id = '12345'", "Dr. Jane Smith");
foreach (var line in logLines)
{
    Console.WriteLine(line);
}

var userMessage = msg_Framework.CreateFolder(@"C:\Tingen_Data\Logs");
Console.WriteLine(userMessage);
// Output:
// [2026-05-15 10:30:45.12345] Folder "C:\Tingen_Data\Logs" did not exist, and was created...

// Start message:
Console.WriteLine(msg_Maintenance.RefreshTranslations("FormId"));
// Output: [2026-05-15 10:30:45.12345] Refreshing the FormId translation table...

// Completion message:
Console.WriteLine(msg_Maintenance.RefreshTranslations());
// Output: complete. [2026-05-15 10:30:46.54321]

// Start message:
Console.WriteLine(msg_Maintenance.RefreshBlueprints("ErrorMessages"));
// Output: [2026-05-15 10:30:45.12345] Refreshing the ErrorMessages translation table...

// Completion message:
Console.WriteLine(msg_Maintenance.RefreshBlueprints());
// Output: complete. [2026-05-15 10:30:46.54321]

var logMessage = msg_TngnWscv.MissingComponent(sentOptionObject, "_OpenIncident");
Console.WriteLine(logMessage);
// Output:
// The OptionObject ("ScriptLinkStandard.Objects.OptionObject2015") and/or Script Parameter ("_OpenIncident") are missing.

var runtimeConfig = RuntimeConfig.Load(Settings.Default, "1.2.3");
var avatarSystem  = runtimeConfig["AvatarSystem"];
var mode          = runtimeConfig["Mode"];

Console.WriteLine($"Avatar system: {avatarSystem}, Mode: {mode}");

var settings = new { AvatarSystem = "LIVE", Mode = "enabled" };

// Write with indentation:
DuJson.ExportToLocalFile(settings, @"C:\Tingen_Data\config\settings.json");

// Write without indentation:
DuJson.ExportToLocalFile(settings, @"C:\Tingen_Data\config\settings.json", formatJson: false);

var settings = DuJson.ImportFromLocalFile<AppSettings>(@"C:\Tingen_Data\config\settings.json");
if (settings != null)
{
    Console.WriteLine(settings.AvatarSystem);
}

var folders = TngnWsvcDataFolders.Load(
    avatarSystem:     "LIVE",
    avatarUserId:     "jsmith",
    serverDataPath:   @"C:\Tingen_Data",
    sessionDate:      "2026-05-15",
    sessionStartTime: "103045");

Console.WriteLine(folders.DataRoot);
// Output: C:\Tingen_Data\LIVE

Console.WriteLine(folders.AppDataRoot);
// Output: C:\Tingen_Data\LIVE\AppData

Console.WriteLine(folders.Session);
// Output: C:\Tingen_Data\LIVE\Session\2026-05-15\jsmith\103045

var framework = TngnWsvcFramework.Load(
    avatarSystem:     "LIVE",
    avatarUserId:     "jsmith",
    serverDataPath:   @"C:\Tingen_Data",
    serverWwwPath:    @"C:\inetpub\wwwroot",
    sessionDate:      "2026-05-15",
    sessionStartTime: "103045");

Console.WriteLine(framework.TngnWsvcDataFolder.Log);
// Output: C:\Tingen_Data\LIVE\AppData\Log

Console.WriteLine(framework.TngnWsvcWwwFolder.WwwRoot);
// Output: C:\inetpub\wwwroot\LIVE

var framework = TngnWsvcFramework.Load(
    "LIVE", "jsmith", @"C:\Tingen_Data", @"C:\inetpub\wwwroot",
    "2026-05-15", "103045");

// Ensure all "LIVE" data folders exist on disk:
TngnWsvcFramework.Verify(framework, traceLogLimit: 3, avatarSystem: "LIVE", sessionDate: "2026-05-15");

var wwwFolders = TngnWsvcWwwFolders.Load("LIVE", @"C:\inetpub\wwwroot");

Console.WriteLine(wwwFolders.WwwRoot);
// Output: C:\inetpub\wwwroot\LIVE

Console.WriteLine(wwwFolders.AppDataRoot);
// Output: C:\inetpub\wwwroot\LIVE\bin\AppData

Console.WriteLine(wwwFolders.Blueprint);
// Output: C:\inetpub\wwwroot\LIVE\bin\AppData\Blueprint

CriticalLog.Create(
    avatarUserId:       "jsmith",
    tngnWsvcDataFolder: tngnWsvcSession.Framework.TngnWsvcDataFolder,
    logTitle:           "WSVC9999",
    logMsg:             "Unhandled exception while processing request.",
    exeAsm:             AvatarOptionObject.ExeAsm,
    classPath:          "Core/Avatar/AvatarOptionObject.cs",
    methodName:         "ToReturn",
    lineNumber:         57);
// Writes:
//   {Session}\WSVC9999-jsmith.critical
//   {Log}\WSVC9999-jsmith.critical

var blueprint =
    "[~SESSION~DATE~TIME~] ~ASSEMBLY~::~CLASS~.~METHOD~ (line ~LINE~): ~LOG~MESSAGE~";

var content = CriticalLog.LogContent(
    logBlueprint: blueprint,
    logMsg:       "Database connection failed.",
    exeAsm:       "TingenWebService",
    classPath:    "Core/Avatar/AvatarOptionObject.cs",
    methodName:   "ToReturn",
    lineNumber:   57);

Console.WriteLine(content);
// Example output:
// [05/15/2026-10:30:45] TingenWebService::AvatarOptionObject.ToReturn (line 57): Database connection failed.

DebugLog.Create(
    logMsg:     "Reached validation step with value = 42",
    classPath:  "Core/Avatar/AvatarOptionObject.cs",
    methodName: "ToReturn",
    lineNumber: 57);
// Writes a file similar to:
//   C:\Tingen_Data\.development\debug\3045-12345-AvatarOptionObject-ToReturn-57.debug

ErrorLog.Create(
    avatarUserId:       "jsmith",
    tngnWsvcDataFolder: tngnWsvcSession.Framework.TngnWsvcDataFolder,
    exeAsm:             AvatarOptionObject.ExeAsm,
    errCode:            "WSVC2491",
    errMsg:             "The form ID was not found in the translation table.",
    classPath:          "Core/Avatar/AvatarScriptParameter.cs",
    methodName:         "SpecificFormRequest",
    lineNumber:         62);
// Writes:
//   {Session}\WSVC2491-jsmith.error
//   {Log}\WSVC2491-jsmith.error

var blueprint =
    "[~SESSION~DATE~TIME~] [~ERROR~CODE~] ~ASSEMBLY~::~CLASS~.~METHOD~ (line ~LINE~): ~ERROR~MESSAGE~";

var content = ErrorLog.LogContent(
    logBlueprint: blueprint,
    errCode:      "WSVC2491",
    errMsg:       "The form ID was not found in the translation table.",
    exeAsm:       "TingenWebService",
    classPath:    "Core/Avatar/AvatarScriptParameter.cs",
    methodName:   "SpecificFormRequest",
    lineNumber:   62);

Console.WriteLine(content);
// Example output:
// [05/15/2026-10:30:45] [WSVC2491] TingenWebService::AvatarScriptParameter.SpecificFormRequest (line 62): The form ID was not found in the translation table.

HistoryLog.Create(
    logFolder:   @"C:\Tingen_Data\LIVE\AppData\History",
    sessionDate: "2026-05-15",
    logMsg:      $"[{HistoryLog.Timestamp()}] Service started.{Environment.NewLine}");
// Appends to:
//   C:\Tingen_Data\LIVE\AppData\History\2026-05-15.history

var timestamp = HistoryLog.Timestamp();
Console.WriteLine(timestamp);
// Example output: 2026-05-15 10:30:45.12345

// Called from AvatarOptionObject.ToReturn at line 57:
var info = LogComponents.GetCallerInfo();
Console.WriteLine(info);
// Output: AvatarOptionObject-ToReturn-57

var rawXml    = "<Settings><Mode>enabled</Mode></Settings>";
var formatted = LogComponents.FormatXml(rawXml);
Console.WriteLine(formatted);
// Output:
// ```xml
//     <Settings><Mode>enabled</Mode></Settings>
// ```

var logSettings = LogSettings.Load(traceLogLimit: "3", sessionLogLimit: "100");
Console.WriteLine(logSettings.TraceLogLimit);   // 3
Console.WriteLine(logSettings.SessionLogLimit); // 100

var name = LogUtility.GetClassName(@"C:\src\Core\Avatar\AvatarOptionObject.cs");
Console.WriteLine(name);
// Output: AvatarOptionObject

LogUtility.AppendLocal(
    @"C:\Tingen_Data\LIVE\AppData\History\2026-05-15.history",
    $"[{HistoryLog.Timestamp()}] Service started.{Environment.NewLine}");

SessionLog.Create(tngnWsvcSession);
// Writes:
//   {Session}\jsmith.session

var blueprint = File.ReadAllText(blueprintPath);
var content   = SessionLog.Outline(
    logBlueprint:           blueprint,
    sessionDetail:          tngnWsvcSession.Runtime,
    sessionScriptParameter: tngnWsvcSession.ScriptParameter.OriginalScriptParameter);

var entry = log_DoseChangeEval.PrescriberIsAuthorizing(
    LogComponents.GetCallerInfo(),
    staffMemberIdQuery,
    physicianApprover);

SessionLog.AddToSessionLog(tngnWsvcSession, entry);

TraceLog.Create(
    traceLevel:    1,
    traceLogLimit: tngnWsvcSession.LogSetting.TraceLogLimit,
    sessionFolder: tngnWsvcSession.Framework.TngnWsvcDataFolder.Session,
    exeAsm:        AvatarOptionObject.ExeAsm,
    classPath:     "Core/Avatar/AvatarOptionObject.cs",
    methodName:    "ToReturn",
    lineNumber:    57);
// Writes a file similar to:
//   {Session}\3045-12345-TingenWebService-AvatarOptionObject-ToReturn-57.trace

if (!DailyMaintenance.DailyLogPathExists(@"C:\Tingen_Data\LIVE\AppData\Log\Daily"))
{
    // create the folder, etc.
}

member.example:
The following example shows how a session pipeline calls QuickCheck after the
session folder has been resolved:

int traceLogLimit = runtimeConfig.TraceLogLimit;
string sessionFolder = tngnWsvcDataFolders.CurrentSession;

SessionMaintenance.QuickCheck(traceLogLimit, sessionFolder);
